import sys, json
class Solution:
    def totalNQueens(self, n):
        col=[False]*n; d1=[False]*(2*n-1); d2=[False]*(2*n-1)
        def dfs(r):
            if r==n: return 1
            ans=0
            for c in range(n):
                if col[c] or d1[r-c+n-1] or d2[r+c]: continue
                col[c]=d1[r-c+n-1]=d2[r+c]=True
                ans += dfs(r+1)
                col[c]=d1[r-c+n-1]=d2[r+c]=False
            return ans
        return dfs(0)

